import{_ as a,C as i,o as l,c as u,j as t,a as r,E as o,a2 as s}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"Zones","description":"","frontmatter":{"title":"Zones"},"headers":[],"relativePath":"guide/zones.md","filePath":"guide/zones.md"}'),d={name:"guide/zones.md"};function g(c,e,p,h,m,v){const n=i("Capture");return l(),u("div",null,[e[0]||(e[0]=t("h1",{id:"zones",tabindex:"-1"},[r("Zones "),t("a",{class:"header-anchor",href:"#zones","aria-label":'Permalink to "Zones"'},"​")],-1)),e[1]||(e[1]=t("p",null,[r("Les notes de la mémoire sont rangées dans des "),t("strong",null,"zones"),r(", qui disent à quoi sert une note. Chaque zone a son écran : une liste que vous pouvez filtrer, trier et ouvrir, avec de quoi créer, renommer, déplacer ou retirer une note.")],-1)),o(n,{name:"zone-liste",alt:"La zone Connaissance en liste, filtrée sur « Cette année » : une ligne par note, avec son type et son projet."}),e[2]||(e[2]=s('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><h3 id="les-neuf-zones" tabindex="-1">Les neuf zones <a class="header-anchor" href="#les-neuf-zones" aria-label="Permalink to &quot;Les neuf zones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Zone</th><th>Dossier</th><th>Ce qu&#39;elle accueille</th></tr></thead><tbody><tr><td><strong>Boîte de réception</strong></td><td><code>00-inbox</code></td><td>Les captures rapides, en attente de classement.</td></tr><tr><td><strong>Sessions</strong></td><td><code>10-episodes</code></td><td>Les archives de session, projet par projet.</td></tr><tr><td><strong>Connaissance</strong></td><td><code>20-knowledge</code></td><td>Les notes de connaissance et les faits sur le code.</td></tr><tr><td><strong>Procédures</strong></td><td><code>30-procedures</code></td><td>Comment faire une chose, pas à pas.</td></tr><tr><td><strong>Principes</strong></td><td><code>40-principles</code></td><td>Les principes, avec leur force : ligne rouge, heuristique, préférence ou règle d&#39;action.</td></tr><tr><td><strong>Objectifs</strong></td><td><code>50-goals</code></td><td>Les objectifs, avec leur horizon et leur échéance.</td></tr><tr><td><strong>Personnes</strong></td><td><code>60-people</code></td><td>Les fiches de personnes.</td></tr><tr><td><strong>Cognition</strong></td><td><code>70-cognition</code></td><td>Ce qui porte sur votre manière de travailler et de penser.</td></tr><tr><td><strong>Système</strong></td><td><code>99-meta</code></td><td>Les gabarits et les fichiers de service de la mémoire.</td></tr></tbody></table><h3 id="dans-la-barre-laterale" tabindex="-1">Dans la barre latérale <a class="header-anchor" href="#dans-la-barre-laterale" aria-label="Permalink to &quot;Dans la barre latérale&quot;">​</a></h3><ul><li>Les zones sont listées sous <strong>Zones de la mémoire</strong>, chacune avec une barre de couleur et le nombre de notes qu&#39;elle contient (sous-dossiers compris).</li><li>Un petit chevron déplie les sous-dossiers d&#39;une zone, avec leur propre compte. Une zone sans sous-dossier n&#39;a pas de chevron.</li><li>Quand elles existent, <strong>Cognition</strong> et <strong>Système</strong> sont rangées derrière la ligne <strong>Avancé</strong>, repliée par défaut.</li></ul><h3 id="dans-l-ecran-d-une-zone" tabindex="-1">Dans l&#39;écran d&#39;une zone <a class="header-anchor" href="#dans-l-ecran-d-une-zone" aria-label="Permalink to &quot;Dans l&#39;écran d&#39;une zone&quot;">​</a></h3><ul><li><strong>En-tête</strong> : le nom de la zone (suivi du sous-dossier si vous en avez ouvert un), sa description et le nombre de notes avec les dates extrêmes (« 4 notes, du 04.07.2026 au 30.09.2026 »). À droite, une petite jauge de <strong>densité</strong> (la part de la zone dans la mémoire) et les boutons <strong>Dossiers</strong> et <strong>Nouveau</strong>.</li><li><strong>Filtres</strong> : des pastilles <strong>Tous</strong>, <strong>Cette année</strong>, <strong>Ce mois</strong>, <strong>Sans projet</strong>, et <strong>Avec liens</strong> quand la zone compte des citations. Quand les notes de la zone sont datées, une pastille de tri <strong>Dépôt décroissant</strong> / <strong>Dépôt croissant</strong>. À droite : « 4 notes · 4 affichées ».</li><li><strong>Liste</strong> : une ligne par note, avec un titre à gauche et des colonnes qui dépendent de la zone (voir plus bas). Un tiret « — » signale une valeur absente.</li><li>Une zone vide affiche « Zone vide » et dit ce qu&#39;elle accueille. Un filtre qui écarte tout affiche « Aucune note ne correspond à ce filtre ».</li></ul><h3 id="les-colonnes-de-chaque-zone" tabindex="-1">Les colonnes de chaque zone <a class="header-anchor" href="#les-colonnes-de-chaque-zone" aria-label="Permalink to &quot;Les colonnes de chaque zone&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Zone</th><th>Colonnes</th><th>À savoir</th></tr></thead><tbody><tr><td><strong>Sessions</strong></td><td>Un rail <strong>Projets</strong> à gauche, puis l&#39;écran du projet choisi</td><td>Le rail donne le nombre de notes de chaque projet. L&#39;écran du projet montre ses chiffres (<strong>Notes</strong>, <strong>Archives</strong>, <strong>Zones</strong>, <strong>Dernière session</strong>), son historique et ses archives.</td></tr><tr><td><strong>Connaissance</strong></td><td><strong>Savoir</strong>, <strong>Type</strong>, <strong>Projet</strong>, <strong>Provenance</strong></td><td>Une ligne « Par type : concept 1 · référence 1… » résume la zone. Une étiquette « accepté » marque les notes acceptées.</td></tr><tr><td><strong>Principes</strong></td><td>Un rail <strong>Projets</strong>, puis <strong>Principe</strong>, <strong>Projet</strong>, <strong>Force</strong></td><td>La force est <strong>Ligne rouge</strong>, <strong>Heuristique</strong>, <strong>Préférence</strong> ou <strong>Règle d&#39;action</strong> ; sinon « force non déclarée ».</td></tr><tr><td><strong>Objectifs</strong></td><td><strong>Objectif</strong>, <strong>Projet</strong>, <strong>Statut</strong>, <strong>Échéance</strong></td><td>Les objectifs sont groupés par <strong>Court terme</strong>, <strong>Moyen terme</strong>, <strong>Long terme</strong> (ou « Horizon non déclaré »). Statut : « ouvert », « en cours », « atteint », « abandonné ».</td></tr><tr><td><strong>Système</strong></td><td><strong>Fiche</strong>, <strong>Projet</strong>, <strong>Citations</strong></td><td>La colonne dit « citée par 3 notes ».</td></tr><tr><td><strong>Boîte de réception</strong>, <strong>Procédures</strong>, <strong>Personnes</strong>, <strong>Cognition</strong></td><td><strong>Note</strong>, <strong>Projet</strong></td><td></td></tr></tbody></table><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="ouvrir-une-zone" tabindex="-1">Ouvrir une zone <a class="header-anchor" href="#ouvrir-une-zone" aria-label="Permalink to &quot;Ouvrir une zone&quot;">​</a></h3><p>Dans la barre latérale, cliquez sur le nom d&#39;une zone, ou sur l&#39;un de ses sous-dossiers après l&#39;avoir déplié. La zone s&#39;ouvre dans un onglet.</p><h3 id="filtrer-et-trier" tabindex="-1">Filtrer et trier <a class="header-anchor" href="#filtrer-et-trier" aria-label="Permalink to &quot;Filtrer et trier&quot;">​</a></h3><p>Dans la ligne des pastilles, cliquez sur <strong>Cette année</strong>, <strong>Ce mois</strong>, <strong>Sans projet</strong> ou <strong>Avec liens</strong> pour ne garder que les notes concernées ; <strong>Tous</strong> les ramène toutes. Le compte à droite dit combien de notes sont affichées sur le total. La pastille de tri inverse l&#39;ordre : les dépôts les plus récents d&#39;abord, ou les plus anciens.</p><p>Dans <strong>Sessions</strong>, les notes se rangent par âge de dépôt : <strong>Dépôt frais</strong> (30 jours au plus), <strong>Tassé</strong> (jusqu&#39;à un an) et <strong>Scellé</strong> (au-delà).</p><h3 id="ouvrir-une-note" tabindex="-1">Ouvrir une note <a class="header-anchor" href="#ouvrir-une-note" aria-label="Permalink to &quot;Ouvrir une note&quot;">​</a></h3><p>Cliquez sur son titre : la note s&#39;ouvre dans un onglet. Pour la lire et la modifier, voir <a href="/Kessho/guide/atom.html">Atome et éditeur</a>.</p><h3 id="creer-une-note-ou-un-dossier" tabindex="-1">Créer une note ou un dossier <a class="header-anchor" href="#creer-une-note-ou-un-dossier" aria-label="Permalink to &quot;Créer une note ou un dossier&quot;">​</a></h3><ol><li>Dans l&#39;en-tête de la zone, cliquez sur <strong>Nouveau</strong>, puis sur <strong>Note</strong> ou <strong>Dossier</strong>.</li><li>Pour une note, remplissez <strong>Titre</strong>, éventuellement <strong>Nom de fichier</strong> (sinon il est déduit du titre), <strong>Portée</strong> (<strong>Travail</strong>, <strong>Personnel</strong> ou <strong>Les deux</strong>) et, quand des modèles existent, <strong>Modèle</strong>.</li><li>Cliquez sur <strong>Créer</strong>. La note ou le dossier est créé dans la zone (ou le sous-dossier) que vous regardez.</li></ol><h3 id="renommer-ou-deplacer-une-note" tabindex="-1">Renommer ou déplacer une note <a class="header-anchor" href="#renommer-ou-deplacer-une-note" aria-label="Permalink to &quot;Renommer ou déplacer une note&quot;">​</a></h3>',20)),o(n,{name:"zone-menu-ligne",alt:"Le menu d'une ligne de zone, ouvert au clic droit : ouvrir, renommer, déplacer, retirer."}),e[3]||(e[3]=s('<ol><li>Faites un clic droit sur la ligne de la note : le menu propose <strong>Ouvrir</strong>, <strong>Renommer</strong>, <strong>Déplacer</strong> et <strong>Retirer</strong>.</li><li><strong>Renommer</strong> : changez le <strong>Titre</strong> et le <strong>Nom de fichier</strong> (ou cochez « Garder le nom de fichier actuel »), puis <strong>Valider</strong>. <strong>Déplacer</strong> : choisissez la <strong>Destination</strong>, puis <strong>Déplacer</strong>.</li><li>Kessho montre d&#39;abord « Ce que l&#39;opération va faire » : les fichiers qui seront mis à jour, lien par lien. Cliquez sur <strong>Appliquer</strong> pour confirmer, ou sur <strong>Annuler</strong>.</li><li>Un bandeau « Résultat de la dernière opération » dit ce qui a été fait et propose <strong>Annuler</strong> : les fichiers et les liens reviennent à leur état d&#39;avant.</li></ol><h3 id="retirer-une-note" tabindex="-1">Retirer une note <a class="header-anchor" href="#retirer-une-note" aria-label="Permalink to &quot;Retirer une note&quot;">​</a></h3><ol><li>Clic droit sur la note, puis <strong>Retirer</strong>. Vous pouvez ajouter un <strong>Motif (facultatif)</strong>.</li><li>La note part dans la corbeille de la mémoire (<code>.trash</code>), avec un message qui dit d&#39;où elle vient. Elle peut être remise en place.</li><li>Si d&#39;autres notes la citent, Kessho les liste sous <strong>Cité par</strong> et le bouton devient <strong>Retirer quand même</strong>.</li></ol><h3 id="gerer-les-dossiers" tabindex="-1">Gérer les dossiers <a class="header-anchor" href="#gerer-les-dossiers" aria-label="Permalink to &quot;Gérer les dossiers&quot;">​</a></h3><p>Cliquez sur <strong>Dossiers</strong> dans l&#39;en-tête : la liste des sous-dossiers de la zone s&#39;affiche, chacun avec <strong>Renommer</strong>, <strong>Déplacer</strong> et <strong>Supprimer</strong>. Un dossier marqué « tenu par Kessho » ne se modifie pas ici. Supprimer un dossier le met dans la corbeille avec tout son contenu ; il peut être remis en place.</p><h3 id="voir-ce-qu-un-agent-vient-de-changer" tabindex="-1">Voir ce qu&#39;un agent vient de changer <a class="header-anchor" href="#voir-ce-qu-un-agent-vient-de-changer" aria-label="Permalink to &quot;Voir ce qu&#39;un agent vient de changer&quot;">​</a></h3>',6)),o(n,{name:"fraicheur",alt:"Le témoin de fraîcheur, en haut à droite : un agent vient d'écrire dans la zone Procédures, le témoin s'allume et dit ce qui a bougé."}),e[4]||(e[4]=t("p",null,[r("Quand un agent écrit dans la mémoire pendant que l'application est ouverte, le "),t("strong",null,"témoin de fraîcheur"),r(" s'allume. C'est la petite pastille en haut à droite, à côté de votre profil.")],-1)),e[5]||(e[5]=t("ol",null,[t("li",null,"Cliquez sur la pastille. Le panneau dit depuis quand : « Vu il y a une seconde. » Sans rien de nouveau, il dit « Aucun changement depuis l'ouverture. »"),t("li",null,"Sous « Mouvements depuis le dernier rechargement », chaque zone touchée est listée avec son nombre de mouvements. Si une note a changé sans qu'aucune zone change de taille, le panneau le dit aussi."),t("li",null,[r("Cliquez sur "),t("strong",null,"Relire"),r(" pour recharger l'écran actif : les listes montrent alors le nouvel état.")])],-1)),e[6]||(e[6]=t("p",null,"Le témoin compte des mouvements, pas une taille : ajouter puis retirer une note en fait deux.",-1))])}const z=a(d,[["render",g]]);export{f as __pageData,z as default};
